def changes(sid):
    d={}
    for r in csv.DictReader(open(VALUES_CSV)):
        if r['timeseries_id']==sid:
            d[r['timestamp']]=float(r['value'])
    out=[]; pv=None
    for t in sorted(d):
        v=d[t]
        if pv is None or abs(v-pv)>0.2: out.append((t,v))
        pv=v
    return out
